import{_ as d,o as a,c as r,a2 as e}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"Теория Плоскостей и Классификация","description":"","frontmatter":{},"headers":[],"relativePath":"ru/80-位面理论与分类.md","filePath":"ru/80-位面理论与分类.md","lastUpdated":1789183869000}'),i={name:"ru/80-位面理论与分类.md"};function l(o,t,h,n,s,p){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="теория-плоскостеи-и-классификация" tabindex="-1">Теория Плоскостей и Классификация <a class="header-anchor" href="#теория-плоскостеи-и-классификация" aria-label="Permalink to &quot;Теория Плоскостей и Классификация&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Позиция</th><th>Содержание</th></tr></thead><tbody><tr><td>№ документа</td><td>80</td></tr><tr><td>Модуль</td><td>Межплоскостное взаимодействие и правила времени</td></tr><tr><td>Ключевые слова</td><td>Теория плоскостей, классификация плоскостей, барьеры законов, координаты плоскостей, Вселенная Хэнъюань</td></tr></tbody></table><h2 id="i-базовое-определение-плоскости" tabindex="-1">I. Базовое определение плоскости <a class="header-anchor" href="#i-базовое-определение-плоскости" aria-label="Permalink to &quot;I. Базовое определение плоскости&quot;">​</a></h2><p>В рамках Изначальной Вселенной Ваньлин Хэнмао (Вселенной Хэнъюань) «плоскость» обозначает область существования, ограниченную набором относительно стабильных законов и обладающую независимой пространственно-временной непрерывностью. Плоскость — не просто «другой мир», а конкретизированная проекция сети законов в разных интервалах параметров. Каждая плоскость обладает уникальными физическими константами, плотностью энергии, скоростью течения времени и уровнем активности сознания, и эти параметры вместе составляют «отпечаток законов» плоскости.</p><p>Существование плоскостей проистекает из неоднородности сети законов Вселенной Хэнъюань. В процессе действия изначальных законов вселенной, из-за различий в распределении энергии, возмущениях сознания и исторической эволюции, естественным образом сформировались бесчисленные области законов с разными параметрами. Эти области разделены «барьерами законов», чья прочность зависит от степени различия параметров законов между соседними плоскостями — чем больше различие, тем толще барьер и тем выше сложность пересечения.</p><p>Механизм Якоря занимает центральное положение в теории плоскостей. Якорь по сути — стабильный узел сети законов; он может не только поддерживать стабильность законов своей плоскости, но и служить якорным эталоном для межплоскостных соединений. Все интерактивные действия — межплоскостная навигация, связь и археология — должны использовать Якорь как начало координат для позиционирования и калибровки.</p><h2 id="ii-система-классификации-плоскостеи" tabindex="-1">II. Система классификации плоскостей <a class="header-anchor" href="#ii-система-классификации-плоскостеи" aria-label="Permalink to &quot;II. Система классификации плоскостей&quot;">​</a></h2><p>Плоскости Вселенной Хэнъюань разделяются по параметрам законов, уровням энергии и степени развития цивилизации на следующие пять основных категорий:</p><table tabindex="0"><thead><tr><th>Категория</th><th>Характеристики законов</th><th>Плотность энергии</th><th>Типичная форма цивилизации</th><th>Сложность навигации</th></tr></thead><tbody><tr><td>Плоскость Материальной Доминанты</td><td>Физические законы доминируют, энергия латентна</td><td>Низкая</td><td>Технологическая цивилизация, начинающая культивационная цивилизация</td><td>Низкая</td></tr><tr><td>Плоскость Проявленной Энергии</td><td>Энергетические законы полупроявлены, системы культивации зрелые</td><td>Средняя</td><td>Средне-высокая культивационная цивилизация, магическая цивилизация</td><td>Средняя</td></tr><tr><td>Плоскость Доминанты Сознания</td><td>Законы сознания проявлены, материя формируется волей</td><td>Высокая</td><td>Цивилизация духовных тел, цивилизация агрегатов сознания</td><td>Высокая</td></tr><tr><td>Плоскость Разломов Законов</td><td>Законы нестабильны, множество разломов законов</td><td>Чрезвычайно высокая и хаотичная</td><td>Дикие плоскости, плоскости руин</td><td>Чрезвычайно высокая</td></tr><tr><td>Плоскость, Близкая к Изначальной</td><td>Близка к изначальным законам вселенной, параметры приближаются к пределам</td><td>Приближается к изначальной</td><td>Верховная цивилизация, стражи плоскостей</td><td>Теоретический предел</td></tr></tbody></table><p>Помимо пяти основных категорий, существуют также некоторые особые типы плоскостей, в том числе: Зеркальные Плоскости (параллельные существования, высокосимметричные по параметрам законов с определённой плоскостью), Промежуточные Плоскости (переходные области между барьерами законов двух главных плоскостей), Спящие Плоскости (древние плоскости с крайне низкой активностью законов, почти остановившиеся) и Новорождённые Плоскости (молодые плоскости, недавно сформировавшиеся в сети законов, с ещё нестабильными параметрами).</p><h2 id="iii-координаты-плоскостеи-и-принцип-позиционирования" tabindex="-1">III. Координаты плоскостей и принцип позиционирования <a class="header-anchor" href="#iii-координаты-плоскостеи-и-принцип-позиционирования" aria-label="Permalink to &quot;III. Координаты плоскостей и принцип позиционирования&quot;">​</a></h2><p>Предпосылка межплоскостного взаимодействия — точное позиционирование плоскостей. Вселенная Хэнъюань установила «четырёхмерную систему координат плоскостей» на основе Якоря, где каждая плоскость однозначно определяется четырьмя параметрами:</p><ol><li><strong>Код отпечатка законов</strong>: уникальный идентификатор, генерируемый хешированием центральных параметров законов плоскости, длиной 128 бит.</li><li><strong>Степень связи с Якорем</strong>: сила соединения между плоскостью и известной сетью Якорей, в диапазоне от 0 до 1.</li><li><strong>Коэффициент скорости времени</strong>: отношение скорости течения времени плоскости к стандартному времени Вселенной Хэнъюань, обычно от 0,1 до 10.</li><li><strong>Число пространственных измерений</strong>: количество воспринимаемых пространственных измерений плоскости, обычно от 3 до 11.</li></ol><p>Способы получения координат плоскостей включают: автоматическое обнаружение сетью Якоря, ретроспекцию межплоскостных коммуникационных сигналов, остаточные координаты в археологических руинах и ручные записи межплоскостных навигаторов. Все подтверждённые координаты плоскостей вносятся в «Центральную Базу Координат Плоскостей Вселенной Хэнъюань», единообразно поддерживаемую Управлением Плоскостей при Собрании Якоря.</p><h2 id="iv-естественное-взаимодеиствие-между-плоскостями" tabindex="-1">IV. Естественное взаимодействие между плоскостями <a class="header-anchor" href="#iv-естественное-взаимодеиствие-между-плоскостями" aria-label="Permalink to &quot;IV. Естественное взаимодействие между плоскостями&quot;">​</a></h2><p>Даже без активной навигации между плоскостями существуют естественные явления взаимодействия. Самое распространённое — «просачивание законов»: из-за локально слабых барьеров между соседними плоскостями небольшое количество параметров законов взаимно просачивается, вызывая локальные аномальные явления. Например, изредка возникающие в плоскостях материальной доминанты «сверхъестественные события» часто вызваны просачиванием законов из соседней плоскости проявленной энергии.</p><p>Другое естественное взаимодействие — «резонанс плоскостей». Когда коды отпечатков законов двух плоскостей имеют высокую степень сходства, между ними возникает периодический резонанс законов, проявляющийся в появлении в обеих плоскостях в определённые периоды времени сходных исторических событий, траекторий цивилизаций и даже личных судеб. Резонанс плоскостей — важный объект исследования археологии плоскостей; анализируя закономерности резонанса, можно предположить цивилизационное состояние неизвестных плоскостей.</p><h2 id="заключение" tabindex="-1">Заключение <a class="header-anchor" href="#заключение" aria-label="Permalink to &quot;Заключение&quot;">​</a></h2><p>Теория плоскостей — теоретический краеугольный камень всех практик межплоскостного взаимодействия. Точное понимание сущности, классификации и принципов позиционирования плоскостей — предпосылка разработки правил навигации, этических норм и механизмов профилактики и контроля. Исследование плоскостей Вселенной Хэнъюань всегда следует принципу «познание прежде всего, взаимодействие с осторожностью», обеспечивая, чтобы при расширении границ цивилизации не причинялось необратимого вмешательства в автономную эволюцию ни одной плоскости.</p><h2 id="связанные-документы" tabindex="-1">Связанные документы <a class="header-anchor" href="#связанные-документы" aria-label="Permalink to &quot;Связанные документы&quot;">​</a></h2><ul><li>81-位面穿梭规则 (Правила Межплоскостной Навигации)</li><li>88-跨位面伦理准则 (Межплоскостные Этические Нормы)</li><li>28-跨位面锚点连接 (Межплоскостные Соединения Якоря)</li></ul>',21)])])}const b=d(i,[["render",l]]);export{c as __pageData,b as default};
